--
-- The July files were added to the archive mid-session (Rick, 2026-08-02),
-- after this backfill was first drafted covering only May+June (the archive
-- had no July order file at that point — only "Reserved Titles — July
-- 2026.pdf", the reserved-titles REPORT, not a submitted-order record).
-- Confirms F102's live-instance finding directly: prh-order-2026-07-26.txt
-- line contains `75960621668000111,7` — the exact extra 7 copies that,
-- against June's already-submitted 5, produced PRH's 12-copy order against
-- 7 reservations (5 surplus).
--
-- ENRICHMENT CAVEAT: item_code/title/foc_date were looked up against
-- STAGING's catalog (this table currently only exists on staging). Staging's
-- catalog is a lighter test dataset that does not fully mirror production's
-- historical May/June/July catalog — 708 of 857 codes (83%) had no staging
-- match, so their title/foc_date are NULL below. This does NOT affect
-- correctness: order_submissions has no FK to catalog, and the app's
-- duplicate-check and backorder-risk panel both match on order_code alone
-- (title/foc_date are descriptive-only, read by nobody in the shipped code).
-- When this table is promoted to PRODUCTION, the equivalent backfill should
-- be regenerated against production's catalog, which matched 100% of the
-- May/June codes during this session's S1 measurement (production is where
-- the real order history and its catalog both actually live).
--
-- Count check performed before this file was generated: 857 source lines
-- across 6 files, 857 rows below (1:1, no dedup needed — no duplicate
-- codes within any single source file, verified by `sort | uniq -d`
-- returning nothing on all 6).
-- ============================================================================

-- Pre-check: table is empty (expected — first backfill)
SELECT count(*) FROM public.order_submissions;


-- Verify: 857 rows landed, split as expected
SELECT distributor, catalog_month, count(*) AS rows, sum(quantity) AS total_qty
FROM public.order_submissions
GROUP BY distributor, catalog_month
ORDER BY catalog_month, distributor;
-- Expected: PRH/2026-05=93, Lunar/2026-05=55, PRH/2026-06=131, Lunar/2026-06=137,
--           PRH/2026-07=212, Lunar/2026-07=229

SELECT count(*) AS null_title_rows FROM public.order_submissions WHERE title IS NULL;
-- Expected: 708 (see ENRICHMENT CAVEAT above — cosmetic only, not a defect)

-- Confirms F102's live-instance finding is now represented in the ledger:
-- June (qty 5) + July (qty 7) = 12 total submitted, against 7 reservations.
SELECT order_code, catalog_month, submitted_on, quantity
FROM public.order_submissions
WHERE order_code = '75960621668000111'
ORDER BY submitted_on;
-- Expected: two rows, quantities 5 (2026-06-27) and 7 (2026-07-26)
